    'a_new_key_with_the_same_scopes_and_approval_policy_is_c_c8fff425' => 'A new key with the same scopes and approval policy is created and shown once. The current key keeps working for 24 hours, so whatever uses it can switch without an outage.',
    'a_one_time_sign_in_link_by_email_turning_this_off_also_eeae7dbf' => 'A one-time sign-in link by email. Turning this off also stops links already sent from working.',
